	}
	useFileTools := *fileTools || request.FileTools
	registry, operations, err := buildTools(ctx, absolute, storeDirectory, sessionID, useFileTools)
	if err != nil {
		return err
	}
	encodedMeta, err := json.Marshal(metaEvent{
		Type: "meta", SessionID: string(sessionID), Model: model, Workspace: absolute,
	})
	if err != nil {
		return fmt.Errorf("encode meta event: %w", err)
	}
	if _, err := fmt.Fprintf(output, "%s\n", encodedMeta); err != nil {
		return fmt.Errorf("write meta event: %w", err)
	}
	observerID := store.AddObserver(func(_ session.ID, item sessionstore.Item) {
		encoded, err := json.Marshal(item)
		if err != nil {
			return
		}
		fmt.Fprintf(output, "%s\n", encoded)
	})
	defer store.RemoveObserver(observerID)

	inputs, err := inbox.New(ctx, restored.ExternalInputIDs)
	if err != nil {
		return fmt.Errorf("open inbox: %w", err)
	}
	settingsPayload, err := json.Marshal(inbox.ControlMessage{
		Mode: inbox.UpdateSettings,
		Parameters: inbox.Settings{
			ReasoningEffort: reasoningEffort(request.ThinkingLevel),
		},
	})
	if err != nil {
		return fmt.Errorf("encode settings: %w", err)
	}
	if err := inputs.Submit(ctx, inbox.Input{
		ID: inbox.ID(uuid.New().String()), Kind: inbox.InputControl, Payload: settingsPayload,
	}); err != nil {
		return fmt.Errorf("submit settings: %w", err)
	}
	for _, message := range messageList(request) {
		payload, err := json.Marshal(message.Content)
		if err != nil {
			return fmt.Errorf("encode message: %w", err)
		}
		if err := inputs.Submit(ctx, inbox.Input{
			ID: inbox.ID(uuid.New().String()), Kind: inbox.InputExternal, Payload: payload,
		}); err != nil {
			return fmt.Errorf("submit message: %w", err)
		}
	}
	stopPayload, err := json.Marshal(inbox.ControlMessage{Mode: inbox.StopWhenIdle})
	if err != nil {
		return fmt.Errorf("encode stop: %w", err)
	}
	if err := inputs.Submit(ctx, inbox.Input{
		ID: inbox.ID(uuid.New().String()), Kind: inbox.InputControl, Payload: stopPayload,
	}); err != nil {
		return fmt.Errorf("submit stop: %w", err)
	}

	builder := contextbuilder.NewBuilder()
	builder.SetModel(llm.Model{ID: model, ReasoningEffort: reasoningEffort(request.ThinkingLevel)})
	builder.SetSystemPrompt(systemPrompt(request, useFileTools))
	for _, definition := range registry.StaticDefinitions() {
		builder.AddTool(definition.Tool)
	}

	return coordinator.New(coordinator.Dependencies{
		SessionID:      sessionID,
		Inbox:          inputs,
		Restored:       restored,
		Sessions:       store,
		ContextBuilder: builder,
		LLM:            client,
		Tools:          registry,
		Operations:     operations,
	}).Run(ctx)
}

func parseRequest(args []string, prompt string, stdinReader io.Reader) (Request, error) {
	var request Request
	switch {
	case prompt != "":
		request.Prompt = &prompt
	case len(args) == 1 && strings.HasPrefix(strings.TrimSpace(args[0]), "{"):
		if err := json.Unmarshal([]byte(args[0]), &request); err != nil {
			return Request{}, fmt.Errorf("decode request: %w", err)
		}
	default:
		encoded, err := io.ReadAll(stdinReader)
		if err != nil {
			return Request{}, fmt.Errorf("read request: %w", err)
		}
		if len(strings.TrimSpace(string(encoded))) > 0 {
			if err := json.Unmarshal(encoded, &request); err != nil {
				return Request{}, fmt.Errorf("decode request: %w", err)
			}
		}
	}
	for _, message := range request.Messages {
		switch message.Role {
		case "user", "assistant":
		default:
			return Request{}, fmt.Errorf("message role must be user or assistant, got %q", message.Role)
		}
	}
	return request, nil
}

func messageList(request Request) []Message {
	if len(request.Messages) > 0 {
		return request.Messages
	}
	if request.Prompt != nil {
		return []Message{{Role: "user", Content: *request.Prompt}}
	}
	return nil
}

const upstreamSystemPrompt = `You are an AI agent running inside an isolated sandbox container.

## Guidelines
- Save output files to the workspace root.
- For large datasets, inspect a sample first before processing everything.
`

// systemPrompt mirrors upstream's default in pristine mode and uses the
// pair-programming prompt only when the extra file tools are available.
func systemPrompt(request Request, useFileTools bool) string {
	if request.SystemPrompt != nil && strings.TrimSpace(*request.SystemPrompt) != "" {
		return *request.SystemPrompt
	}
	if useFileTools {
		return defaultSystemPrompt
	}
	return upstreamSystemPrompt
}

func openSession(ctx context.Context, store *localfile.Store, requested *string) (session.ID, sessionstore.ResumeState, error) {
	id := session.ID(uuid.New().String())
	if requested != nil && strings.TrimSpace(*requested) != "" {
		id = session.ID(strings.TrimSpace(*requested))
	}
	restored, err := store.Resume(ctx, id)
	if err == nil {
		return id, restored, nil
	}
	if !errors.Is(err, fs.ErrNotExist) {
		return "", sessionstore.ResumeState{}, fmt.Errorf("resume session %q: %w", id, err)
	}
	snapshot, err := store.Create(ctx, id)
	if err != nil {
		return "", sessionstore.ResumeState{}, fmt.Errorf("create session %q: %w", id, err)
	}
	return id, sessionstore.ResumeState{Snapshot: snapshot}, nil
}

func reasoningEffort(level string) llm.ReasoningEffort {
	switch level {
	case "low":
		return llm.ReasoningEffortLow
	case "medium":
		return llm.ReasoningEffortMedium
	case "xhigh":
		return llm.ReasoningEffortXHigh
	case "max":
		return llm.ReasoningEffortMax
	default:
		return llm.ReasoningEffortHigh
	}
}

func newClient(request Request, getenv func(string) string) (llm.Adapter, string, func() error, error) {
	provider := request.Provider
	if provider == "" {
		provider = getenv("UNREAL_TUI_PROVIDER")
	}
	if provider == "" {
		provider = defaultProvider
	}
	model := request.Model
	if model == "" {
		model = getenv("UNREAL_TUI_MODEL")
	}
	maxAttempts := 4
	switch provider {
	case "openai":
		apiKey := getenv("OPENAI_API_KEY")
		if apiKey == "" {
			return nil, "", nil, fmt.Errorf("OPENAI_API_KEY is not set")
		}
		if model == "" {
			model = defaultModel
		}
		client, err := openai.NewClient(openai.Config{APIKey: apiKey, BaseURL: getenv("OPENAI_BASE_URL"), MaxAttempts: &maxAttempts})
		if err != nil {
			return nil, "", nil, err
		}
		return client, model, client.Close, nil
	case "commandcode":
		apiKey := getenv("COMMANDCODE_API_KEY")
		if apiKey == "" {
			return nil, "", nil, fmt.Errorf("COMMANDCODE_API_KEY is not set")
		}
		if model == "" {
			model = "z-ai/glm-5.3-flash"
		}
		client, err := openai.NewClient(openai.Config{APIKey: apiKey, BaseURL: "https://api.commandcode.ai/provider/v1", MaxAttempts: &maxAttempts})
		if err != nil {
			return nil, "", nil, err
		}
		return client, model, client.Close, nil
	case "openrouter":
		apiKey := getenv("OPENROUTER_API_KEY")
		if apiKey == "" {
			return nil, "", nil, fmt.Errorf("OPENROUTER_API_KEY is not set")
		}
		if model == "" {
			model = defaultModel
		}
		client, err := openrouter.NewClient(openrouter.Config{APIKey: apiKey, BaseURL: "https://openrouter.ai/api/v1", MaxAttempts: &maxAttempts})
		if err != nil {
			return nil, "", nil, err
		}
		return client, model, client.Close, nil
	case "fireworks":
		apiKey := getenv("FIREWORKS_AI_API_KEY")
		if apiKey == "" {
			return nil, "", nil, fmt.Errorf("FIREWORKS_AI_API_KEY is not set")
		}
		if model == "" {
			model = defaultModel
		}
		client, err := fireworks.NewClient(fireworks.Config{APIKey: apiKey, BaseURL: "https://api.fireworks.ai/inference/v1", MaxAttempts: &maxAttempts})
		if err != nil {
			return nil, "", nil, err
		}
		return client, model, client.Close, nil
	case "ollama":
		if model == "" {
			model = "qwen3:8b"
		}
		client, err := ollama.NewClient(ollama.Config{BaseURL: ollama.BaseURL, MaxAttempts: &maxAttempts})
		if err != nil {
			return nil, "", nil, err
		}
		return client, model, client.Close, nil
	default:
		return nil, "", nil, fmt.Errorf("unknown provider %q (want openai, commandcode, openrouter, fireworks, or ollama)", provider)
	}
}

func stdin() io.Reader { return os.Stdin }

// buildTools mirrors upstream's tool configuration exactly (same shell
// resolution, skill discovery, and enabled names); when useFileTools is true
// the Read/Write/Edit tools are added on top.
func buildTools(
	ctx context.Context,
	workspace, storeDirectory string,
	sessionID session.ID,
	useFileTools bool,
) (tool.Registry, operation.Manager, error) {
	shell := strings.TrimSpace(os.Getenv("SHELL"))
	if shell == "" {
		shell = "/bin/sh"
	}
	operationDirectory := filepath.Join(storeDirectory, "operations", string(sessionID))
	if err := os.MkdirAll(operationDirectory, 0o700); err != nil {
		return nil, nil, fmt.Errorf("create operation directory: %w", err)
	}
	skills, _ := tool.DiscoverSkills(filepath.Join(workspace, ".harness", "skills"))
	names := []string{tool.BashName, tool.ViewImageName}
	if len(skills) != 0 {
		names = append(names, tool.SkillUseName)
	}
	static := tool.StaticTranslators{
		Bash:      bash.New(bash.Config{Shell: shell, Directory: workspace, BaseDirectory: operationDirectory}),
		ViewImage: viewimage.New(viewimage.Config{Directory: workspace}),
	}
	inner := tool.NewRegistry(static, names...)
	for _, skill := range skills {
		if _, err := inner.RegisterSkill(skill); err != nil {
			return nil, nil, fmt.Errorf("register skill %q: %w", skill.Path, err)
		}
	}
	local := operation.NewLocalOperationManager(ctx)
	if !useFileTools {
		return inner, local, nil
	}
	return filetools.NewRegistry(inner, workspace), filetools.NewManager(ctx, local, workspace), nil
}

package tui

import (
	"strings"

	"github.com/charmbracelet/bubbles/spinner"
	"github.com/charmbracelet/bubbles/textarea"
	"github.com/charmbracelet/bubbles/viewport"
	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"
	"path/filepath"
)

// blockKind is one transcript entry.
type blockKind int

const (
	blockMeta blockKind = iota
	blockUser
	blockAssistant
	blockReasoning
	blockTool
	blockError
	blockDivider
)

// toolCard is the state of one tool call shown as a card.
type toolCard struct {
	callID  string
	name    string
	argsRaw string
	status  string // running, ok, failed, canceled
	errText string
}

// block is one transcript block; tool blocks carry a card.
type block struct {
	kind     blockKind
	text     string
	tool     *toolCard
	rendered string // glamour cache for assistant blocks
	width    int    // width the cache was rendered at
}

type Model struct {
	workspace string
	provider  string
	model     string
	fileTools bool

	viewport   viewport.Model
	textarea   textarea.Model
	spinner    spinner.Model
	blocks     []block
	toolBlocks map[string]int // callID → blocks index
	sessionID  string
	turnUsage  [2]int64 // last turn: in, out tokens
	sessionIn  int64
	sessionOut int64

	running bool
	aborted bool
	width   int
	height  int

	cmdCancel func()

	// session picker state
	picking   bool
	sessions  []sessionEntry
	pickIndex int
	loading   bool

	events chan tea.Msg
}

func New(workspace, provider, model string, fileTools bool) Model {
	absolute, err := filepath.Abs(workspace)
	if err != nil {
		absolute = workspace
	}
	ta := textarea.New()
	ta.Placeholder = "Describe a task… (/help for commands, Esc to abort/quit, Ctrl+C to quit)"
	ta.Prompt = "❯ "
	ta.CharLimit = 32_000
	ta.SetWidth(80)
	ta.SetHeight(1)
	ta.Focus()
	ta.ShowLineNumbers = false

	return Model{
		workspace:  absolute,
		provider:   provider,
		model:      model,
		fileTools:  fileTools,
		textarea:   ta,
		viewport:   viewport.New(80, 20),
		spinner:    spinner.New(spinner.WithSpinner(spinner.MiniDot)),
		toolBlocks: map[string]int{},
	}
}

func (m Model) Init() tea.Cmd {
	return tea.Batch(textarea.Blink, m.spinner.Tick)
}

// ---- messages ----

type (
	turnDoneMsg   struct{ err error }
	blockMsg      struct{ b block }
	toolStatusMsg struct {
		callID  string
		name    string
		status  string
		errText string
	}
	metaMsg struct {
		sessionID string
		model     string
	}
	sessionsMsg struct {
		entries []sessionEntry
		err     error
	}
	usageMsg struct {
		in  int64
		out int64
	}
)

// ---- update ----

func (m Model) Update(message tea.Msg) (tea.Model, tea.Cmd) {
	var cmds []tea.Cmd
	switch msg := message.(type) {
	case tea.WindowSizeMsg:
		m.width, m.height = msg.Width, msg.Height
		m.viewport.Width = msg.Width
		m.viewport.Height = msg.Height - 6
		m.textarea.SetWidth(msg.Width)
		m.refresh()
	case spinner.TickMsg:
		if m.running || m.loading {
			var cmd tea.Cmd
			m.spinner, cmd = m.spinner.Update(msg)
			cmds = append(cmds, cmd)
		}
	case metaMsg:
		if m.sessionID == "" {
			m.sessionID = msg.sessionID
		}
		if m.model == "" {
			m.model = msg.model
		}
		m.appendBlock(block{kind: blockMeta, text: "session " + short(msg.sessionID) + " · " + msg.model + " · " + m.workspace})
	case usageMsg:
		m.turnUsage = [2]int64{msg.in, msg.out}
		m.sessionIn += msg.in
		m.sessionOut += msg.out
		m.refresh()
	case blockMsg:
		m.appendBlock(msg.b)
	case toolStatusMsg:
		m.updateToolCard(msg)
	case sessionsMsg:
		m.loading = false
		if msg.err != nil {
			m.appendBlock(block{kind: blockError, text: "list sessions: " + msg.err.Error()})
		} else {
			m.picking = true
			m.sessions = msg.entries
			m.pickIndex = 0
		}
		m.refresh()
	case turnDoneMsg:
		m.running = false
		m.cmdCancel = nil
		if m.aborted {
			m.appendBlock(block{kind: blockDivider, text: "turn aborted"})
			m.aborted = false
		} else if msg.err != nil {
			m.appendBlock(block{kind: blockError, text: "agent exited: " + msg.err.Error()})
		}
		m.refresh()
	case tea.KeyMsg:
		if m.picking {
			return m.updatePicker(msg)
		}
		switch msg.Type {
		case tea.KeyCtrlC:
			if m.running && m.cmdCancel != nil {
				m.cmdCancel()
			}
			return m, tea.Quit
		case tea.KeyEsc:
			if m.running && m.cmdCancel != nil {
				m.aborted = true
				m.cmdCancel()
			} else {
				return m, tea.Quit
			}
		case tea.KeyEnter:
			if strings.Contains(msg.String(), "alt+enter") || strings.Contains(msg.String(), "shift+enter") {
				m.textarea, _ = m.textarea.Update(msg)
				m.resizeEditor()
			} else if !m.running {
				input := strings.TrimSpace(m.textarea.Value())
				if input != "" {
					m.textarea.Reset()
					m.textarea.SetHeight(1)
					if strings.HasPrefix(input, "/") {
						cmds = append(cmds, m.command(input)...)
					} else {
						m.appendBlock(block{kind: blockUser, text: input})
						m.running = true
						m.events = make(chan tea.Msg, 256)
						m.refresh()
						m.startTurn(input)
						cmds = append(cmds, m.spinner.Tick)
					}
				}
			}
		default:
			m.textarea, _ = m.textarea.Update(msg)
			m.resizeEditor()
		}
	}
	// While a turn is active, exactly one listen() must be pending at any
	// time; whatever message was just handled consumed it, so re-arm here on
	// every path. When the turn ends (turnDoneMsg sets running=false) the
	// chain stops naturally.
	if m.running && m.events != nil {
		cmds = append(cmds, m.listen())
	}
	var cmd tea.Cmd
	m.viewport, cmd = m.viewport.Update(message)
	cmds = append(cmds, cmd)
	return m, tea.Batch(cmds...)
}

func (m *Model) resizeEditor() {
	lines := strings.Count(m.textarea.Value(), "\n") + 1
	m.textarea.SetHeight(min(max(lines, 1), 8))
}

func (m *Model) appendBlock(b block) {
	if b.kind == blockTool && b.tool != nil {
		if _, exists := m.toolBlocks[b.tool.callID]; exists {
			return
		}
		m.toolBlocks[b.tool.callID] = len(m.blocks)
	}
	m.blocks = append(m.blocks, b)
	m.refresh()
}

func (m *Model) updateToolCard(msg toolStatusMsg) {
	index, exists := m.toolBlocks[msg.callID]
	if !exists {
		card := &toolCard{callID: msg.callID, name: msg.name, status: msg.status, errText: msg.errText}
		m.appendBlock(block{kind: blockTool, tool: card})
		return
	}
	card := m.blocks[index].tool
	card.status = msg.status
	if msg.errText != "" {
		card.errText = msg.errText
	}
	if msg.name != "" && card.name == "" {
		card.name = msg.name
	}
	m.refresh()
}

func (m *Model) command(input string) []tea.Cmd {
	fields := strings.Fields(input)
	switch fields[0] {
	case "/quit", "/exit":
		if m.cmdCancel != nil {
			m.cmdCancel()
		}
		return []tea.Cmd{tea.Quit}
	case "/new":
		m.sessionID = ""
		m.appendBlock(block{kind: blockDivider, text: "new session — next prompt starts fresh"})
	case "/model":
		if len(fields) == 1 {
			m.appendBlock(block{kind: blockMeta, text: "model: " + orDefault(m.model, "(provider default)")})
		} else {
			m.model = fields[1]
			m.appendBlock(block{kind: blockMeta, text: "model set to " + m.model})
		}
	case "/resume":
		m.loading = true
		m.refresh()
		return []tea.Cmd{listSessions(m.workspace), m.spinner.Tick}
	case "/help":
		m.appendBlock(block{kind: blockMeta, text: strings.Join([]string{
			"commands:",
			"  /new              start a fresh session",
			"  /resume           pick a previous session",
			"  /model [id]       show or set the model",
			"  /quit             exit (alias /exit)",
			"keys: Enter send · Esc abort/quit · Ctrl+C quit",
		}, "\n")})
	default:
		m.appendBlock(block{kind: blockError, text: "unknown command " + fields[0] + " (/help)"})
	}
	m.refresh()
	return nil
}

func orDefault(value, fallback string) string {
	if strings.TrimSpace(value) == "" {
		return fallback
	}
	return value
}

// ---- picker ----

func (m Model) updatePicker(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch msg.Type {
	case tea.KeyCtrlC:
		return m, tea.Quit
	case tea.KeyEsc:
		m.picking = false
		m.refresh()
		return m, nil
	case tea.KeyUp:
		if m.pickIndex > 0 {
			m.pickIndex--
		}
	case tea.KeyDown:
		if m.pickIndex < len(m.sessions)-1 {
			m.pickIndex++
		}
	case tea.KeyEnter:
		if m.pickIndex >= 0 && m.pickIndex < len(m.sessions) {
			entry := m.sessions[m.pickIndex]
			m.picking = false
			m.loadSession(entry)
			return m, nil
		}
	}
	m.refresh()
	return m, nil
}

func (m *Model) loadSession(entry sessionEntry) {
	blocks, sessionID, err := replaySession(m.workspace, entry)
	if err != nil {
		m.appendBlock(block{kind: blockError, text: "load session: " + err.Error()})
		m.refresh()
		return
	}
	m.sessionID = sessionID
	m.toolBlocks = map[string]int{}
	m.blocks = blocks
	m.appendBlock(block{kind: blockDivider, text: "resumed session " + short(sessionID) + " — new prompts continue it"})
	m.refresh()
}

// ---- view ----

func (m *Model) refresh() {
	m.viewport.SetContent(m.renderTranscript())
	m.viewport.GotoBottom()
}

func (m Model) View() string {
	if m.width == 0 {
		return "starting…"
	}
	if m.picking {
		return m.viewPicker()
	}
	modelLabel := orDefault(m.model, "(default model)")
	sessionLabel := "new"
	if m.sessionID != "" {
		sessionLabel = "session " + short(m.sessionID)
	}
	header := titleStyle.Render("unreal-agent") +
		dimStyle.Render("  "+m.workspace+" · "+modelLabel+" · "+sessionLabel)
	status := ""
	if m.loading {
		status = statusStyle.Render(m.spinner.View() + " loading sessions…")
	} else if m.running {
		status = statusStyle.Render(m.spinner.View() + " working…")
	} else {
		status = dimStyle.Render("idle")
		if m.sessionIn > 0 || m.sessionOut > 0 {
			status += dimStyle.Render("  last turn: " + humanCount(m.turnUsage[0]) + " in / " + humanCount(m.turnUsage[1]) + " out")
			status += dimStyle.Render("  ·  session: " + humanCount(m.sessionIn) + " in / " + humanCount(m.sessionOut) + " out")
		}
	}
	return lipgloss.JoinVertical(lipgloss.Left,
		header,
		strings.Repeat("─", max(m.width, 1)),
		m.viewport.View(),
		strings.Repeat("─", max(m.width, 1)),
		status,
		m.textarea.View(),
	)
}

var (
	titleStyle     = lipgloss.NewStyle().Bold(true).Foreground(lipgloss.Color("12"))
	userStyle      = lipgloss.NewStyle().Bold(true).Foreground(lipgloss.Color("10"))
	assistantStyle = lipgloss.NewStyle()
	toolStyle      = lipgloss.NewStyle().Foreground(lipgloss.Color("8"))
	dimStyle       = lipgloss.NewStyle().Foreground(lipgloss.Color("8")).Italic(true)
	errorStyle     = lipgloss.NewStyle().Foreground(lipgloss.Color("9"))
	statusStyle    = lipgloss.NewStyle().Foreground(lipgloss.Color("6"))
	diffAddStyle   = lipgloss.NewStyle().Foreground(lipgloss.Color("10"))
	diffDelStyle   = lipgloss.NewStyle().Foreground(lipgloss.Color("9"))
)

// keep sync imported for future shared state; avoids accidental value copies.
package tui

import (
	"bufio"
	"encoding/json"
	"io"
	"strings"

	tea "github.com/charmbracelet/bubbletea"
)

// itemKind mirrors the JSONL item kinds emitted by the runner.
const (
	kindMeta           = "meta"
	kindModelResponse  = "model_response"
	kindToolCallStatus = "tool_call_status"
	kindError          = "error"
)

// ---- wire shapes (runner JSONL) ----

type wireItem struct {
	Kind string          `json:"Kind"`
	Data json.RawMessage `json:"Data"`
}

type wireError struct {
	Type    string `json:"type"`
	Message string `json:"message"`
}

type wireMeta struct {
	Type      string `json:"type"`
	SessionID string `json:"session_id"`
	Model     string `json:"model"`
	Workspace string `json:"workspace"`
}

type wireModelResponse struct {
	Response wireResponse `json:"Response"`
}

type wireResponse struct {
	Output []wireOutputItem `json:"Output"`
	Usage  wireUsage        `json:"Usage"`
}

type wireUsage struct {
	InputTokens  int64 `json:"InputTokens"`
	OutputTokens int64 `json:"OutputTokens"`
}

type wireOutputItem struct {
	Type string          `json:"Type"`
	Data json.RawMessage `json:"Data"`
}

type wireMessage struct {
	Role string `json:"Role"`
	Text string `json:"Text"`
}

type wireToolCall struct {
	CallID string          `json:"CallID"`
	Name   string          `json:"Name"`
	Args   json.RawMessage `json:"Arguments"`
}

type wireReasoning struct {
	Summary []string `json:"Summary"`
}

type wireToolCallStatus struct {
	CallID     string     `json:"CallID"`
	Status     wireStatus `json:"Status"`
	Operations []wireOp   `json:"Operations"`
}

type wireStatus struct {
	Error string `json:"Error"`
}

type wireOp struct {
	ID     string `json:"ID"`
	Type   string `json:"Type"`
	Status string `json:"Status"`
}

func decodeItems(reader io.Reader, handle func(kind string, data json.RawMessage)) {
	scanner := bufio.NewScanner(reader)
	scanner.Buffer(make([]byte, 0, 1024*1024), 8*1024*1024)
	for scanner.Scan() {
		line := scanner.Bytes()
		if len(strings.TrimSpace(string(line))) == 0 {
			continue
		}
		var meta wireMeta
		if err := json.Unmarshal(line, &meta); err == nil && meta.Type == "meta" {
			handle(kindMeta, line)
			continue
		}
		var errEvent wireError
		if err := json.Unmarshal(line, &errEvent); err == nil && errEvent.Type == "error" {
			handle(kindError, line)
			continue
		}
		var item wireItem
		if err := json.Unmarshal(line, &item); err != nil {
			continue
		}
		handle(item.Kind, item.Data)
	}
}

// toolInfo is the model-facing tool call recorded when it appears in a model
// response, so the later tool_call_status can render a full card.
type toolInfo struct {
	name    string
	argsRaw string
}

// eventParser turns JSONL wire items into UI messages.
type eventParser struct {
	toolCalls map[string]toolInfo
}

func newEventParser() *eventParser {
	return &eventParser{toolCalls: map[string]toolInfo{}}
}

// parse converts one wire item into zero or more UI messages.
func (parser *eventParser) parse(kind string, data json.RawMessage) []tea.Msg {
	switch kind {
	case kindMeta:
		var meta wireMeta
		if err := json.Unmarshal(data, &meta); err == nil {
			return []tea.Msg{metaMsg{sessionID: meta.SessionID, model: meta.Model}}
		}
	case kindModelResponse:
		var response wireModelResponse
		if err := json.Unmarshal(data, &response); err != nil {
			return nil
		}
		var messages []tea.Msg
		for _, output := range response.Response.Output {
			switch output.Type {
			case "message":
				var message wireMessage
				if err := json.Unmarshal(output.Data, &message); err == nil && message.Role == "assistant" && strings.TrimSpace(message.Text) != "" {
					messages = append(messages, blockMsg{b: block{kind: blockAssistant, text: strings.TrimRight(message.Text, "\n")}})
				}
			case "tool_call":
				var call wireToolCall
				if err := json.Unmarshal(output.Data, &call); err == nil && call.CallID != "" {
					parser.toolCalls[call.CallID] = toolInfo{name: call.Name, argsRaw: string(call.Args)}
					messages = append(messages, toolStatusMsg{callID: call.CallID, name: call.Name, status: "running"})
				}
			case "reasoning":
				var reasoning wireReasoning
				if err := json.Unmarshal(output.Data, &reasoning); err == nil && len(reasoning.Summary) > 0 {
					text := collapse(strings.Join(reasoning.Summary, " "), 200)
					if text != "" {
						messages = append(messages, blockMsg{b: block{kind: blockReasoning, text: text}})
					}
				}
			}
		}
		usage := response.Response.Usage
		if usage.InputTokens > 0 || usage.OutputTokens > 0 {
			messages = append(messages, usageMsg{in: usage.InputTokens, out: usage.OutputTokens})
		}
		return messages
	case kindToolCallStatus:
		var status wireToolCallStatus
		if err := json.Unmarshal(data, &status); err != nil {
			return nil
		}
		info := parser.toolCalls[status.CallID]
		if status.Status.Error != "" {
			return []tea.Msg{toolStatusMsg{callID: status.CallID, name: info.name, status: "failed", errText: status.Status.Error}}
		}
		last := ""
		for _, operation := range status.Operations {
			last = operation.Status
		}
		switch last {
		case "completed":
			return []tea.Msg{toolStatusMsg{callID: status.CallID, name: info.name, status: "ok"}}
		case "failed":
			return []tea.Msg{toolStatusMsg{callID: status.CallID, name: info.name, status: "failed"}}
		case "canceled":
			return []tea.Msg{toolStatusMsg{callID: status.CallID, name: info.name, status: "canceled"}}
		default:
			return []tea.Msg{toolStatusMsg{callID: status.CallID, name: info.name, status: "running"}}
		}
	case kindError:
		var errEvent wireError
		if err := json.Unmarshal(data, &errEvent); err == nil {
			return []tea.Msg{blockMsg{b: block{kind: blockError, text: errEvent.Message}}}
		}
	}
	return nil
}

func humanCount(value int64) string {
	switch {
	case value >= 1_000_000:
		return trimFloat(float64(value)/1_000_000) + "M"
	case value >= 1_000:
		return trimFloat(float64(value)/1_000) + "k"
	default:
		return itoa(value)
	}
}

func itoa(value int64) string {
	if value == 0 {
		return "0"
	}
	digits := ""
	negative := value < 0
	if negative {
		value = -value
	}
	for value > 0 {
		digits = string(rune('0'+value%10)) + digits
		value /= 10
	}
	if negative {
		return "-" + digits
	}
	return digits
}

func trimFloat(value float64) string {
	whole := int(value)
	fraction := int((value - float64(whole)) * 10)
	if fraction == 0 {
		return itoa(int64(whole))
	}
	return itoa(int64(whole)) + "." + itoa(int64(fraction))
}

