func (registry *Registry) Skills() []tool.Skill {
	return registry.Inner.Skills()
}

// translator implements tool.Translator for each file tool.
type translator struct {
	opType    operation.Type
	directory string
}

func (translator *translator) Definition() tool.Definition {
	return tool.Definition{Tool: toolSchema(translator.opType)}
}

func toolSchema(opType operation.Type) llm.Tool {
	switch opType {
	case TypeRead:
		return llm.Tool{
			Type:        llm.ToolFunction,
			Name:        ReadName,
			Description: "Read a text file inside the workspace. Returns the file content. Optionally read a slice of lines starting at 1-based offset.",
			Parameters: map[string]any{
				"type": "object",
				"properties": map[string]any{
					"path":   map[string]any{"type": "string", "description": "File path relative to the workspace root."},
					"offset": map[string]any{"type": "integer", "description": "1-based line number to start reading from."},
					"limit":  map[string]any{"type": "integer", "description": "Maximum number of lines to read."},
				},
				"required": []string{"path"},
			},
		}
	case TypeWrite:
		return llm.Tool{
			Type:        llm.ToolFunction,
			Name:        WriteName,
			Description: "Create or overwrite a file inside the workspace with the given content. Parent directories are created as needed.",
			Parameters: map[string]any{
				"type": "object",
				"properties": map[string]any{
					"path":    map[string]any{"type": "string", "description": "File path relative to the workspace root."},
					"content": map[string]any{"type": "string", "description": "Complete new file content."},
				},
				"required": []string{"path", "content"},
			},
		}
	default: // TypeEdit
		return llm.Tool{
			Type:        llm.ToolFunction,
			Name:        EditName,
			Description: "Replace text in an existing file inside the workspace. old_text must match exactly and be unique in the file unless replace_all is true.",
			Parameters: map[string]any{
				"type": "object",
				"properties": map[string]any{
					"path":        map[string]any{"type": "string", "description": "File path relative to the workspace root."},
					"old_text":    map[string]any{"type": "string", "description": "Exact text to replace."},
					"new_text":    map[string]any{"type": "string", "description": "Replacement text."},
					"replace_all": map[string]any{"type": "boolean", "description": "Replace every occurrence instead of requiring a unique match."},
				},
				"required": []string{"path", "old_text", "new_text"},
			},
		}
	}
}

func (translator *translator) Translate(ctx tool.Context, call llm.ToolCall) tool.CallStatus {
	state, limit, err := translator.validate(call.Arguments)
	if err != nil {
		return tool.ErrorStatus(err.Error(), limit)
	}
	encoded, err := json.Marshal(state)
	if err != nil {
		return tool.ErrorStatus(fmt.Sprintf("encode %s arguments: %v", translator.opType, err), limit)
	}
	spec := operation.Spec{
		Type:            translator.opType,
		Version:         1,
		State:           jsontext.Value(encoded),
		MaxOutputLength: defaultMaxOutputLength,
	}
	return tool.CallStatus{WaitingFor: []operation.ID{ctx.Submit(spec)}}
}

func (translator *translator) validate(encoded string) (State, int, error) {
	var state State
	if err := json.Unmarshal([]byte(encoded), &state); err != nil {
		return State{}, 0, fmt.Errorf("decode %s arguments: %w", translator.opType, err)
	}
	if strings.TrimSpace(state.Path) == "" {
		return State{}, 0, fmt.Errorf("path is required")
	}
	relative, err := filepath.Rel(translator.directory, filepath.Join(translator.directory, state.Path))
	if err != nil || relative == ".." || strings.HasPrefix(relative, ".."+string(filepath.Separator)) {
		return State{}, 0, fmt.Errorf("path %q escapes the workspace", state.Path)
	}
	state.Path = relative
	switch translator.opType {
	case TypeRead:
		if state.Offset < 0 || state.Limit < 0 {
			return State{}, 0, fmt.Errorf("offset and limit must be non-negative")
		}
	case TypeWrite:
		// Content may be empty (truncate), nothing to validate.
	case TypeEdit:
		if state.OldText == "" {
			return State{}, 0, fmt.Errorf("old_text is required")
		}
	}
	return state, 0, nil
}

func (translator *translator) TranslateResult(
	callID string,
	status tool.CallStatus,
	operations []operation.Operation,
) (llm.ToolResult, error) {
	if status.Error != "" {
		if len(operations) != 0 {
			return llm.ToolResult{}, fmt.Errorf("%s tool call %q has both a validation error and operations", translator.opType, callID)
		}
		return llm.ToolResult{CallID: callID, Output: []llm.ToolResultOutput{{Kind: llm.ToolResultText, Value: "Error: " + status.Error}}}, nil
	}
	if len(operations) != 1 {
		return llm.ToolResult{}, fmt.Errorf("%s tool call %q has %d operations, want 1", translator.opType, callID, len(operations))
	}
	current := operations[0]
	if current.Type != translator.opType {
		return llm.ToolResult{}, fmt.Errorf("%s tool call %q operation %q has type %q, want %q", translator.opType, callID, current.ID, current.Type, translator.opType)
	}
	var state State
	if err := json.Unmarshal(current.State, &state); err != nil {
		return llm.ToolResult{}, fmt.Errorf("decode %s operation %q state: %w", translator.opType, current.ID, err)
	}
	switch current.Status {
	case operation.StatusReady, operation.StatusAwaiting, operation.StatusCanceling:
		return llm.ToolResult{CallID: callID, Output: []llm.ToolResultOutput{{Kind: llm.ToolResultText, Value: "File operation is still running."}}}, nil
	case operation.StatusCompleted:
		text := state.Result
		if text == "" {
			text = "(no output)"
		}
		return llm.ToolResult{CallID: callID, Output: []llm.ToolResultOutput{{Kind: llm.ToolResultText, Value: text}}}, nil
	case operation.StatusFailed, operation.StatusCanceled:
		message := state.Error
		if message == "" {
			message = string(current.Status) + " " + string(translator.opType) + " operation"
		}
		return llm.ToolResult{CallID: callID, Output: []llm.ToolResultOutput{{Kind: llm.ToolResultText, Value: "Error: " + message}}}, nil
	default:
		return llm.ToolResult{}, fmt.Errorf("%s operation %q has invalid status %q", translator.opType, current.ID, current.Status)
	}
}
package filetools

import (
	"context"
	"encoding/json"
	"encoding/json/jsontext"
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"sync"

	"github.com/unreallabsai/unreal-agent/harness/operation"
)

// Manager wraps a harness operation.Manager, executing file operations itself
// and delegating everything else to the inner manager (Bash, ViewImage, ...).
type Manager struct {
	inner      operation.Manager
	directory  string
	updates    chan operation.Operation
	done       chan operation.Operation
	innerState <-chan operation.Operation

	mu      sync.Mutex
	running map[operation.ID]context.CancelFunc
}

var _ operation.Manager = (*Manager)(nil)

// NewManager wraps inner. File operations resolve relative paths inside
// directory.
func NewManager(ctx context.Context, inner operation.Manager, directory string) *Manager {
	manager := &Manager{
		inner:      inner,
		directory:  directory,
		updates:    make(chan operation.Operation),
		done:       make(chan operation.Operation),
		innerState: inner.Updates(),
		running:    make(map[operation.ID]context.CancelFunc),
	}
	go manager.pump(ctx)
	return manager
}

func (manager *Manager) Add(current operation.Operation) error {
	switch current.Type {
	case TypeRead, TypeWrite, TypeEdit:
		execCtx, cancel := context.WithCancel(context.Background())
		manager.mu.Lock()
		manager.running[current.ID] = cancel
		manager.mu.Unlock()
		go manager.execute(execCtx, current)
		return nil
	default:
		return manager.inner.Add(current)
	}
}

func (manager *Manager) Cancel(id operation.ID, reason string) error {
	manager.mu.Lock()
	cancel, exists := manager.running[id]
	manager.mu.Unlock()
	if exists {
		// The executor observes cancellation and emits the canceled update.
		go cancel()
		return nil
	}
	return manager.inner.Cancel(id, reason)
}

func (manager *Manager) Updates() <-chan operation.Operation {
	return manager.updates
}

func (manager *Manager) pump(ctx context.Context) {
	for {
		select {
		case update := <-manager.innerState:
			select {
			case manager.updates <- update:
			case <-ctx.Done():
				return
			}
		case update := <-manager.done:
			manager.mu.Lock()
			delete(manager.running, update.ID)
			manager.mu.Unlock()
			select {
			case manager.updates <- update:
			case <-ctx.Done():
				return
			}
		case <-ctx.Done():
			return
		}
	}
}

func (manager *Manager) execute(ctx context.Context, current operation.Operation) {
	var request State
	if err := json.Unmarshal(current.State, &request); err != nil {
		manager.finish(current, operation.StatusFailed, State{Path: request.Path, Error: fmt.Sprintf("decode operation state: %v", err)})
		return
	}

	resultState := State{Path: request.Path}
	execCtx, cancel := context.WithCancel(ctx)
	defer cancel()
	err := manager.run(execCtx, current.Type, &request, &resultState)
	if ctx.Err() != nil {
		resultState.Error = "canceled"
		manager.finish(current, operation.StatusCanceled, resultState)
		return
	}
	if err != nil {
		resultState.Error = err.Error()
		manager.finish(current, operation.StatusFailed, resultState)
		return
	}
	manager.finish(current, operation.StatusCompleted, resultState)
}

func (manager *Manager) run(ctx context.Context, opType operation.Type, request *State, result *State) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	path := filepath.Join(manager.directory, request.Path)
	switch opType {
	case TypeRead:
		content, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		lines := strings.Split(string(content), "\n")
		start, end := 0, len(lines)
		if request.Offset > 0 {
			start = min(request.Offset-1, len(lines))
		}
		if request.Limit > 0 {
			end = min(start+request.Limit, len(lines))
		}
		var numbered strings.Builder
		for index := start; index < end; index++ {
			numbered.WriteString(strconv.Itoa(index+1) + "\t" + lines[index] + "\n")
		}
		bounded, _ := operation.BoundOutput(numbered.String(), defaultMaxOutputLength)
		result.Result = bounded
		return nil
	case TypeWrite:
		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
			return err
		}
		if err := os.WriteFile(path, []byte(request.Content), 0o644); err != nil {
			return err
		}
		result.Result = fmt.Sprintf("Wrote %d bytes to %s.", len(request.Content), request.Path)
		return nil
	case TypeEdit:
		content, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		text := string(content)
		count := strings.Count(text, request.OldText)
		if count == 0 {
			return fmt.Errorf("old_text not found in %s", request.Path)
		}
		if count > 1 && !request.ReplaceAll {
			return fmt.Errorf("old_text matches %d times in %s; provide more surrounding text or set replace_all", count, request.Path)
		}
		if request.ReplaceAll {
			text = strings.ReplaceAll(text, request.OldText, request.NewText)
		} else {
			text = strings.Replace(text, request.OldText, request.NewText, 1)
		}
		if err := os.WriteFile(path, []byte(text), 0o644); err != nil {
			return err
		}
		result.Result = fmt.Sprintf("Edited %s: replaced %d occurrence(s).", request.Path, count)
		return nil
	default:
		return fmt.Errorf("unsupported file operation type %q", opType)
	}
}

func (manager *Manager) finish(current operation.Operation, status operation.Status, state State) {
	encoded, err := json.Marshal(state)
	if err != nil {
		status = operation.StatusFailed
		encoded, _ = json.Marshal(State{Path: state.Path, Error: err.Error()})
	}
	current.Status = status
	current.State = jsontext.Value(encoded)
	manager.done <- current
}

package tui

import (
	"strings"

	"github.com/charmbracelet/bubbles/spinner"
	"github.com/charmbracelet/bubbles/textarea"
	"github.com/charmbracelet/bubbles/viewport"
	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"
	"path/filepath"
)

// blockKind is one transcript entry.
type blockKind int

const (
	blockMeta blockKind = iota
	blockUser
	blockAssistant
	blockReasoning
	blockTool
	blockError
	blockDivider
)

// toolCard is the state of one tool call shown as a card.
type toolCard struct {
	callID  string
	name    string
	argsRaw string
	status  string // running, ok, failed, canceled
	errText string
}

// block is one transcript block; tool blocks carry a card.
type block struct {
	kind     blockKind
	text     string
	tool     *toolCard
	rendered string // glamour cache for assistant blocks
	width    int    // width the cache was rendered at
}

type Model struct {
	workspace string
	provider  string
	model     string
	fileTools bool

	viewport   viewport.Model
	textarea   textarea.Model
	spinner    spinner.Model
	blocks     []block
	toolBlocks map[string]int // callID → blocks index
	sessionID  string
	turnUsage  [2]int64 // last turn: in, out tokens
	sessionIn  int64
	sessionOut int64

	running bool
	aborted bool
	width   int
	height  int

	cmdCancel func()

	// session picker state
	picking   bool
	sessions  []sessionEntry
	pickIndex int
	loading   bool

	events chan tea.Msg
}

func New(workspace, provider, model string, fileTools bool) Model {
	absolute, err := filepath.Abs(workspace)
	if err != nil {
		absolute = workspace
	}
	ta := textarea.New()
	ta.Placeholder = "Describe a task… (/help for commands, Esc to abort/quit, Ctrl+C to quit)"
	ta.Prompt = "❯ "
	ta.CharLimit = 32_000
	ta.SetWidth(80)
	ta.SetHeight(1)
	ta.Focus()
	ta.ShowLineNumbers = false

	return Model{
		workspace:  absolute,
		provider:   provider,
		model:      model,
		fileTools:  fileTools,
		textarea:   ta,
		viewport:   viewport.New(80, 20),
		spinner:    spinner.New(spinner.WithSpinner(spinner.MiniDot)),
		toolBlocks: map[string]int{},
	}
}

func (m Model) Init() tea.Cmd {
	return tea.Batch(textarea.Blink, m.spinner.Tick)
}

// ---- messages ----

type (
	turnDoneMsg   struct{ err error }
	blockMsg      struct{ b block }
	toolStatusMsg struct {
		callID  string
		name    string
		status  string
		errText string
	}
	metaMsg struct {
		sessionID string
		model     string
	}
	sessionsMsg struct {
		entries []sessionEntry
		err     error
	}
	usageMsg struct {
		in  int64
		out int64
	}
)

// ---- update ----

func (m Model) Update(message tea.Msg) (tea.Model, tea.Cmd) {
	var cmds []tea.Cmd
	switch msg := message.(type) {
	case tea.WindowSizeMsg:
		m.width, m.height = msg.Width, msg.Height
		m.viewport.Width = msg.Width
		m.viewport.Height = msg.Height - 6
		m.textarea.SetWidth(msg.Width)
		m.refresh()
	case spinner.TickMsg:
		if m.running || m.loading {
			var cmd tea.Cmd
			m.spinner, cmd = m.spinner.Update(msg)
			cmds = append(cmds, cmd)
		}
	case metaMsg:
		if m.sessionID == "" {
			m.sessionID = msg.sessionID
		}
		if m.model == "" {
			m.model = msg.model
		}
		m.appendBlock(block{kind: blockMeta, text: "session " + short(msg.sessionID) + " · " + msg.model + " · " + m.workspace})
	case usageMsg:
		m.turnUsage = [2]int64{msg.in, msg.out}
		m.sessionIn += msg.in
		m.sessionOut += msg.out
		m.refresh()
	case blockMsg:
		m.appendBlock(msg.b)
	case toolStatusMsg:
		m.updateToolCard(msg)
	case sessionsMsg:
		m.loading = false
		if msg.err != nil {
			m.appendBlock(block{kind: blockError, text: "list sessions: " + msg.err.Error()})
		} else {
			m.picking = true
			m.sessions = msg.entries
			m.pickIndex = 0
		}
		m.refresh()
	case turnDoneMsg:
		m.running = false
		m.cmdCancel = nil
		if m.aborted {
			m.appendBlock(block{kind: blockDivider, text: "turn aborted"})
			m.aborted = false
		} else if msg.err != nil {
			m.appendBlock(block{kind: blockError, text: "agent exited: " + msg.err.Error()})
		}
		m.refresh()
	case tea.KeyMsg:
		if m.picking {
			return m.updatePicker(msg)
		}
		switch msg.Type {
		case tea.KeyCtrlC:
			if m.running && m.cmdCancel != nil {
				m.cmdCancel()
			}
			return m, tea.Quit
		case tea.KeyEsc:
			if m.running && m.cmdCancel != nil {
				m.aborted = true
				m.cmdCancel()
			} else {
				return m, tea.Quit
			}
		case tea.KeyEnter:
			if strings.Contains(msg.String(), "alt+enter") || strings.Contains(msg.String(), "shift+enter") {
				m.textarea, _ = m.textarea.Update(msg)
				m.resizeEditor()
			} else if !m.running {
				input := strings.TrimSpace(m.textarea.Value())
				if input != "" {
					m.textarea.Reset()
					m.textarea.SetHeight(1)
					if strings.HasPrefix(input, "/") {
						cmds = append(cmds, m.command(input)...)
					} else {
						m.appendBlock(block{kind: blockUser, text: input})
						m.running = true
						m.events = make(chan tea.Msg, 256)
						m.refresh()
						m.startTurn(input)
						cmds = append(cmds, m.spinner.Tick)
					}
				}
			}
		default:
			m.textarea, _ = m.textarea.Update(msg)
			m.resizeEditor()
		}
	}
	// While a turn is active, exactly one listen() must be pending at any
	// time; whatever message was just handled consumed it, so re-arm here on
	// every path. When the turn ends (turnDoneMsg sets running=false) the
	// chain stops naturally.
	if m.running && m.events != nil {
		cmds = append(cmds, m.listen())
	}
	var cmd tea.Cmd
	m.viewport, cmd = m.viewport.Update(message)
	cmds = append(cmds, cmd)
	return m, tea.Batch(cmds...)
}

func (m *Model) resizeEditor() {
	lines := strings.Count(m.textarea.Value(), "\n") + 1
	m.textarea.SetHeight(min(max(lines, 1), 8))
}

func (m *Model) appendBlock(b block) {
	if b.kind == blockTool && b.tool != nil {
		if _, exists := m.toolBlocks[b.tool.callID]; exists {
			return
		}
		m.toolBlocks[b.tool.callID] = len(m.blocks)
	}
	m.blocks = append(m.blocks, b)
	m.refresh()
}

func (m *Model) updateToolCard(msg toolStatusMsg) {
	index, exists := m.toolBlocks[msg.callID]
	if !exists {
		card := &toolCard{callID: msg.callID, name: msg.name, status: msg.status, errText: msg.errText}
		m.appendBlock(block{kind: blockTool, tool: card})
		return
	}
	card := m.blocks[index].tool
	card.status = msg.status
	if msg.errText != "" {
		card.errText = msg.errText
	}
	if msg.name != "" && card.name == "" {
		card.name = msg.name
	}
	m.refresh()
}

func (m *Model) command(input string) []tea.Cmd {
	fields := strings.Fields(input)
	switch fields[0] {
	case "/quit", "/exit":
		if m.cmdCancel != nil {
			m.cmdCancel()
		}
		return []tea.Cmd{tea.Quit}
	case "/new":
		m.sessionID = ""
		m.appendBlock(block{kind: blockDivider, text: "new session — next prompt starts fresh"})
	case "/model":
		if len(fields) == 1 {
			m.appendBlock(block{kind: blockMeta, text: "model: " + orDefault(m.model, "(provider default)")})
		} else {
			m.model = fields[1]
			m.appendBlock(block{kind: blockMeta, text: "model set to " + m.model})
		}
	case "/resume":
		m.loading = true
		m.refresh()
		return []tea.Cmd{listSessions(m.workspace), m.spinner.Tick}
	case "/help":
		m.appendBlock(block{kind: blockMeta, text: strings.Join([]string{
			"commands:",
			"  /new              start a fresh session",
			"  /resume           pick a previous session",
			"  /model [id]       show or set the model",
			"  /quit             exit (alias /exit)",
			"keys: Enter send · Esc abort/quit · Ctrl+C quit",
		}, "\n")})
	default:
		m.appendBlock(block{kind: blockError, text: "unknown command " + fields[0] + " (/help)"})
	}
	m.refresh()
	return nil
}

func orDefault(value, fallback string) string {
	if strings.TrimSpace(value) == "" {
		return fallback
	}
	return value
}

// ---- picker ----

func (m Model) updatePicker(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch msg.Type {
	case tea.KeyCtrlC:
		return m, tea.Quit
	case tea.KeyEsc:
		m.picking = false
		m.refresh()
		return m, nil
	case tea.KeyUp:
		if m.pickIndex > 0 {
			m.pickIndex--
		}
	case tea.KeyDown:
		if m.pickIndex < len(m.sessions)-1 {
			m.pickIndex++
		}
	case tea.KeyEnter:
		if m.pickIndex >= 0 && m.pickIndex < len(m.sessions) {
			entry := m.sessions[m.pickIndex]
			m.picking = false
			m.loadSession(entry)
			return m, nil
		}
	}
	m.refresh()
	return m, nil
}

func (m *Model) loadSession(entry sessionEntry) {
	blocks, sessionID, err := replaySession(m.workspace, entry)
	if err != nil {
		m.appendBlock(block{kind: blockError, text: "load session: " + err.Error()})
		m.refresh()
		return
	}
	m.sessionID = sessionID
	m.toolBlocks = map[string]int{}
	m.blocks = blocks
	m.appendBlock(block{kind: blockDivider, text: "resumed session " + short(sessionID) + " — new prompts continue it"})
	m.refresh()
}

// ---- view ----

func (m *Model) refresh() {
	m.viewport.SetContent(m.renderTranscript())
	m.viewport.GotoBottom()
}

func (m Model) View() string {
	if m.width == 0 {
		return "starting…"
	}
	if m.picking {
		return m.viewPicker()
	}
	modelLabel := orDefault(m.model, "(default model)")
	sessionLabel := "new"
	if m.sessionID != "" {
		sessionLabel = "session " + short(m.sessionID)
	}
	header := titleStyle.Render("unreal-agent") +
		dimStyle.Render("  "+m.workspace+" · "+modelLabel+" · "+sessionLabel)
	status := ""
	if m.loading {
		status = statusStyle.Render(m.spinner.View() + " loading sessions…")
	} else if m.running {
		status = statusStyle.Render(m.spinner.View() + " working…")
	} else {
		status = dimStyle.Render("idle")
		if m.sessionIn > 0 || m.sessionOut > 0 {
			status += dimStyle.Render("  last turn: " + humanCount(m.turnUsage[0]) + " in / " + humanCount(m.turnUsage[1]) + " out")
			status += dimStyle.Render("  ·  session: " + humanCount(m.sessionIn) + " in / " + humanCount(m.sessionOut) + " out")
		}
	}
