const maxDiffCells = 250_000

// renderDiff shows a real line-level diff of the edit (unchanged lines are
// omitted), not "all old lines then all new lines".
func renderDiff(oldText, newText string, width int) []string {
	oldLines, newLines := diffLines(oldText), diffLines(newText)
	var ops []diffOp
	if len(oldLines)*len(newLines) <= maxDiffCells {
