// diffOp is one changed line: a deletion from the old text or an addition
// from the new text, in document order.
type diffOp struct {
	del  bool
	line string
}

// diffOps computes the changed lines between oldLines and newLines via LCS,
// so a one-line edit inside a large replaced block shows one changed line.
func diffOps(oldLines, newLines []string) []diffOp {
	n, m := len(oldLines), len(newLines)
	lcs := make([][]int, n+1)
	for i := range lcs {
		lcs[i] = make([]int, m+1)
	}
	for i := n - 1; i >= 0; i-- {
		for j := m - 1; j >= 0; j-- {
			if oldLines[i] == newLines[j] {
				lcs[i][j] = lcs[i+1][j+1] + 1
			} else {
				lcs[i][j] = max(lcs[i+1][j], lcs[i][j+1])
			}
		}
	}
	var ops []diffOp
	i, j := 0, 0
	for i < n && j < m {
		if oldLines[i] == newLines[j] {
			i++
			j++
			continue
		}
		if lcs[i+1][j] >= lcs[i][j+1] {
			ops = append(ops, diffOp{del: true, line: oldLines[i]})
			i++
		} else {
			ops = append(ops, diffOp{del: false, line: newLines[j]})
			j++
		}
	}
	for ; i < n; i++ {
		ops = append(ops, diffOp{del: true, line: oldLines[i]})
	}
	for ; j < m; j++ {
		ops = append(ops, diffOp{del: false, line: newLines[j]})
	}
	return ops
}""")

