		t.Errorf("ops[1] = %+v, want addition of \"X\"", ops[1])
	}
}

func TestDiffOpsInsertAndDelete(t *testing.T) {
	ops := diffOps([]string{"a"}, []string{"a", "b", "c"})
	if len(ops) != 2 || ops[0].del || ops[0].line != "b" || ops[1].del || ops[1].line != "c" {
		t.Fatalf("insert: got %v, want additions of b and c", ops)
	}
	ops = diffOps([]string{"a", "b", "c"}, []string{"a"})
	if len(ops) != 2 || !ops[0].del || ops[0].line != "b" || !ops[1].del || ops[1].line != "c" {
		t.Fatalf("delete: got %v, want deletions of b and c", ops)
	}
}

func TestDiffOpsIdenticalAndEmpty(t *testing.T) {
	if ops := diffOps([]string{"a"}, []string{"a"}); len(ops) != 0 {
		t.Fatalf("identical: got %v, want no ops", ops)
	}
	if ops := diffOps(nil, []string{"x"}); len(ops) != 1 || ops[0].del {
		t.Fatalf("empty old: got %v, want one addition", ops)
	}
	if ops := diffOps([]string{"x"}, nil); len(ops) != 1 || !ops[0].del {
		t.Fatalf("empty new: got %v, want one deletion", ops)
	}
}

func TestRenderDiffCollapsesUnchangedLines(t *testing.T) {
	oldText := "one\ntwo\nthree\nfour\nfive\nsix\nseven\neight\nnine\nten"
	newText := "one\ntwo\nTHREE\nfour\nfive\nsix\nseven\neight\nnine\nten"
